MAX_COMPLETIONS = 60
# A recursion error repeats one frame ~1000 times;
# show this many, then "repeated N more times".
MAX_REPEATED_FRAMES = 3
REPO_DIR = Path(__file__).resolve().parents[3]
MAX_ARGS_CHARS = 160
# Names put in the namespace up front; never listed as data objects.
BUILTIN_NAMES = ("pl", "db")


@dataclass
class PyResult:
    stdout: str = ""
    result_repr: str = ""
    error: str = ""
    trace: list[dict[str, str]] = field(default_factory=list)
    """The error as styled parts (see trace_parts); error keeps the plain text."""
    view: View | None = None
    """Set instead of result_repr when the cell's value
    has a view (render.py): a grid, videos, ..."""


@dataclass
class ToolStep:
    tool: str
    args: str
    call_id: str = ""
    """pydantic-ai's tool_call_id: log records made during the call carry it (ToolCallLog)."""
    result_name: str = ""
    """Name the result was bound to (eg 'r1'), '' when the
    tool's result has no view (eg plain text)."""
    result_label: str = ""
    """The result's short summary, eg '12 × 8' or '10 VODs'."""
    result_kind: str = ""
    """The result's view kind (render.py), eg 'table',
    'vods'; its attributes are in widgets.py."""


@dataclass
class Call:
    """The tool inputs that made a shown value (for its tool form, tool_forms.py)."""

    inputs: dict[str, Any]
    value: Any
    """The value they made; the record only counts while this is still what is shown."""
    original: tuple[dict[str, Any], Any] | None = None
    """The agent's own call (inputs, result), kept while
    the form is re-run so it can be put back.
    None for a form added by hand."""
    changed: bool = False
    """The form was run since the agent's call (the view offers to put the original back)."""


@dataclass
class Trashed:
    """A variable cleared from the Variables pane, held for a moment so the clear can be undone
    (Session.clear / restore / purge). Not a cache: nothing reads it but restore.
    """

    value: Any
    size: int
    """Its rough size when cleared (perf.rough_size), for the pane's "freed ..." line."""
    source: str | None = None
    call: Call | None = None
    tool_call_id: str | None = None


@dataclass
class AiResult:
    text: str = ""
    error: str = ""
    """The failure's full standard traceback as plain text ("" if the turn worked)."""
    trace: list[dict[str, str]] = field(default_factory=list)
    """The same traceback as styled parts (see trace_parts), as a cell's error has."""
    steps: list[ToolStep] = field(default_factory=list)
    usage: TurnUsage = field(default_factory=lambda: TurnUsage())


def tokens_text(count: int) -> str:
    """A token count, short: 812, 21.3k, 1M."""
    if count >= 1_000_000:
        return f"{count / 1_000_000:.3g}M"
    return f"{count / 1000:.3g}k" if count >= 1000 else str(count)


def cost_text(cost: float | None) -> str:
    """US dollars, enough digits for a fraction of a cent ($0.0011); '$?' when unknown."""
    return "$?" if cost is None else f"${cost:.2g}" if cost < 0.1 else f"${cost:.2f}"


@dataclass
class TurnUsage:
    """What one agent turn used, summed from each model request's usage (pydantic-ai's
    ModelResponse.usage; cost is what the Gateway reported, or genai-prices' estimate).
    """

    requests: int = 0
    input_tokens: int = 0
    """Every request's whole input, cache reads included,
    so a 3-request turn counts the history 3 times."""
    cache_read_tokens: int = 0
    output_tokens: int = 0
    cost: float | None = None
    """US dollars; None when no request could be priced."""
    unpriced: int = 0
    """Requests with no cost (cost then leaves them out)."""
    context_tokens: int = 0
    """The last request's input + output: how big the conversation
    is now (what the next turn sends)."""
    lines: list[str] = field(default_factory=list)
    """One line per request for the debug log: tokens,
    cost, why it stopped, the tools it called."""

    @classmethod
    def of(cls, messages: Iterable[Any]) -> TurnUsage:
        total = cls()
        for response in messages:
            if not isinstance(response, ModelResponse):
                continue
            usage = response.usage
            total.requests += 1
            total.input_tokens += usage.input_tokens
            total.cache_read_tokens += usage.cache_read_tokens
            total.output_tokens += usage.output_tokens
            if usage.cost is None:
                total.unpriced += 1
            else:
                total.cost = (total.cost or 0) + float(usage.cost)
            total.context_tokens = usage.input_tokens + usage.output_tokens
            tools = [part.tool_name for part in response.parts if isinstance(part, ToolCallPart)]
            total.lines.append(
                " · ".join(
                    [
                        f"{total.requests}. {usage.input_tokens:,} in ({usage.cache_read_tokens:,} cached)",
                        f"{usage.output_tokens:,} out",
                        cost_text(None if usage.cost is None else float(usage.cost)),
                        str(response.finish_reason or "?") + (f" → {', '.join(tools)}" if tools else ""),
                    ]
                )
            )
        return total

    def log_to(self, call: dict[str, Any]) -> None:
        """Put the usage on an "agent" debug-log record (logs._agent shows it)."""
        call["input_tokens"], call["output_tokens"] = self.input_tokens, self.output_tokens
        call["cache_read_tokens"], call["cost"] = self.cache_read_tokens, self.cost
        call["model_requests"] = self.lines

    def summary(self) -> str:
        """The line under an answer, eg '$0.0011 · 21.3k
        in (71% cached) · 812 out · 3 requests'.
        """
        if not self.requests:
            return ""
        cost = cost_text(self.cost) + ("+?" if self.unpriced and self.cost is not None else "")
        cached = f" ({self.cache_read_tokens / self.input_tokens:.0%} cached)" if self.cache_read_tokens else ""
        parts = [cost, f"{tokens_text(self.input_tokens)} in{cached}", f"{tokens_text(self.output_tokens)} out"]
        parts.append(f"{self.requests} request{'s' if self.requests != 1 else ''}")
        return " · ".join(parts)


def log_usage(call: dict[str, Any], session: Any, messages: Iterable[Any]) -> TurnUsage:
    """What an inline chat's model requests used: put on its "agent" debug-log record and added
    to the session's AI cost (as a chat turn does in Session.ask). session may be None.
    """
    usage = TurnUsage.of(messages)
    usage.log_to(call)
    if session is not None:
        session.ai_cost += usage.cost or 0
    return usage


def context_window() -> int | None:
    """The agent's model's context window in tokens (pydantic-ai's model profile, from
    genai-prices' bundled data; offline), None when unknown.
    """
    try:
        return infer_model(ds.ai.agent.model).context_window
    except Exception:  # noqa: BLE001  # a meter without its maximum is fine; never fail the turn
        return None


def _short_path(filename: str) -> tuple[str, str]:
    """(where, display path): where is cell | repo | lib, the path shortened for reading."""
    if filename.startswith("<"):
        return "cell", filename.strip("<>")
    path = Path(filename)
    if "site-packages" in path.parts:
        return "lib", "/".join(path.parts[path.parts.index("site-packages") + 1 :])
    if path.is_relative_to(sys.base_prefix):
        return "lib", "/".join(path.parts[len(Path(sys.base_prefix).parts) + 2 :])  # drop lib/python3.x
    if path.is_relative_to(REPO_DIR):
        return "repo", str(path.relative_to(REPO_DIR))
    return "lib", filename


def _code_parts(frame: traceback.FrameSummary) -> dict[str, str]:
    """The frame's source line split around the failing
    expression: pre, mark (underlined), post.
    """
    line = linecache.getline(frame.filename, frame.lineno or 0).rstrip("\n")
    if not line.strip():
        return {"pre": "", "mark": "", "post": ""}
    indent = len(line) - len(line.lstrip())
    start, end = frame.colno, frame.end_colno
    if start is None or end is None or frame.end_lineno != frame.lineno or not indent <= start < end <= len(line):
        return {"pre": line.strip(), "mark": "", "post": ""}
    # mark only part of the line; marking all of it says nothing
    if line[start:end].strip() == line.strip():
        return {"pre": line.strip(), "mark": "", "post": ""}
    return {"pre": line[indent:start], "mark": line[start:end], "post": line[end:].rstrip()}


def _frame_parts(stack: traceback.StackSummary) -> list[dict[str, str]]:
    parts: list[dict[str, str]] = []

    # the column range too: the last call of a recursion is
    # on the same line but fails elsewhere (eg `1 / 0`)
    def key(frame: traceback.FrameSummary) -> tuple[Any, ...]:
        return frame.filename, frame.lineno, frame.name, frame.colno, frame.end_colno

    for _, run in itertools.groupby(stack, key=key):
        frames = list(run)
        for frame in frames[:MAX_REPEATED_FRAMES]:
            where, path = _short_path(frame.filename)
            parts.append(
                {"kind": "frame", "where": where, "path": path, "line": str(frame.lineno), "func": frame.name}
                | _code_parts(frame)
            )
        if len(frames) > MAX_REPEATED_FRAMES:
            parts.append(
                {"kind": "note", "text": f"[previous line repeated {len(frames) - MAX_REPEATED_FRAMES} more times]"}
            )
    return parts


def trace_parts(error: BaseException, tb: Any) -> list[dict[str, str]]:
    """Everything in the standard traceback, split into parts the UI styles separately.

    Parts, in order: chained earlier exceptions first ("chain" separators), then per exception
    a "head" line, its "frame"s (where = cell | repo | lib; path, line, func; the code as
    pre/mark/post), "note"s, and the "error" (name + message,
    including notes such as polars' "Did you mean").
    """
    parts: list[dict[str, str]] = []
    cause, context = error.__cause__, error.__context__
    if cause is not None:
        parts += trace_parts(cause, cause.__traceback__)
        parts.append({"kind": "chain", "text": "The above exception was the direct cause of the following exception:"})
    elif context is not None and not error.__suppress_context__:
        parts += trace_parts(context, context.__traceback__)
        parts.append({"kind": "chain", "text": "During handling of the above exception, another exception occurred:"})
    stack = traceback.extract_tb(tb) if tb is not None else []
    if stack:
        parts.append({"kind": "head", "text": "Traceback (most recent call last):"})
        parts += _frame_parts(stack)
    if isinstance(error, SyntaxError) and error.lineno is not None:
        where, path = _short_path(error.filename or "<cell>")
        line = (error.text or "").rstrip("\n")
        indent = len(line) - len(line.lstrip())
        start = max((error.offset or 1) - 1, indent)
        end = max(
            error.end_offset - 1 if error.end_offset and error.end_lineno == error.lineno else start + 1, start + 1
        )
        parts.append(
            {
                "kind": "frame",
                "where": where,
                "path": path,
                "line": str(error.lineno),
                "func": "",
                "pre": line[indent:start],
                "mark": line[start:end] or " ",
                "post": line[end:],
            }
        )
        message = error.msg
    else:
        message = str(error)
    notes = getattr(error, "__notes__", None) or []
    module = type(error).__module__
    parts.append(
        {
            "kind": "error",
            "module": "" if module == "builtins" else f"{module}.",
            "name": type(error).__qualname__,
            "text": "\n".join([message, *map(str, notes)]).strip(),
        }
    )
    return parts


def split_trace(parts: list[dict[str, str]]) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    """(hidden, shown): shown is the bottom of the traceback, the frame that raised plus the
    error; hidden is everything above it (earlier frames,
    chained exceptions), collapsed by default.
    """
    frames = [i for i, part in enumerate(parts) if part["kind"] == "frame"]
    if len(frames) <= 1 and not any(part["kind"] == "chain" for part in parts):
        return [], [part for part in parts if part["kind"] != "head"]
    cut = frames[-1] if frames else len(parts) - 1
    return parts[:cut], parts[cut:]


class Session:
    def __init__(self) -> None:
        # when it was made and last asked for (get_session), for the debug panel's System tab
        self.started = self.used = time.time()
        # The session's SmashDb: `db` in the cells, and what a SmashDb console queries.
        self.db = ds.data.init_db()
        self.namespace: dict[str, Any] = {"__name__": "__main__", "pl": pl, "db": self.db}
        self.ai_history: list[Any] = []
        # what the AI cost so far, chat turns and inline chats, in US dollars (TurnUsage.cost;
        # unpriced requests left out)
        self.ai_cost: float = 0.0
        # the chat's size: its last model request's input + output (TurnUsage.context_tokens),
        # what the next turn sends again. An inline chat reads the chat but doesn't add to it.
        self.chat_tokens: int = 0
        self.sources: dict[str, str] = {}
        # Views of notebook cell results, by cell id, so grids
        # can be re-sorted and results opened as tabs.
        self.outputs: dict[str, View] = {}
        # What the user did to each shown view (filter, sort, picked video), by slot:
        # "tab:<name>" for a named value's tab, "chat:<name>" for the same value shown inline
        # in the chat, "cell:<id>" for a cell's result.
        self.ui: dict[str, Ui] = {}
        # Tabs the user closed: name -> the value it held (compared
        #                       by identity). Only the tab goes; the name stays
        # in Python. It comes back when the name is bound to something new, or is opened again.
        self.closed: dict[str, Any] = {}
        # The tool call behind a value, by the name it is bound to (r1, ...) or a cell's slot
        # ("cell:<id>"): recorded when the agent's tool returns and when a tool form is run.
        self.calls: dict[str, Call] = {}
        # The agent's tool call that made each result (r1 -> its tool_call_id), for the debug
        # log's "requests of this result" (logs.in_focus). Kept when the name is rebound.
        self.tool_call_ids: dict[str, str] = {}
        self._table_count = 0
        # The last batch cleared from the Variables pane (name -> what it was), until it is put
        # back (restore) or dropped for good (purge: a timer in state.py, "Free now", the next
        # clear). trash_seq numbers the batches, so a
        # timer only drops the batch it was set for.
        self.trash: dict[str, Trashed] = {}
        self.trash_seq = 0
        # what the last purge dropped: rough bytes and how
        # many variables (the pane's "freed ..." line)
        self.freed = 0
        self.freed_names = 0

    # -- python ---------------------------------------------------------------

    def run_python(self, code: str, label: str = "cell") -> PyResult:
        """Run code in the persistent namespace; a trailing
        bare expression is the result, as in Jupyter.

        label (eg "In [3]") names the cell in tracebacks. Its source is registered with
        linecache under that name, so traceback lines from this cell show their code, even when
        a function defined here fails in a later cell.
        """
        result = PyResult()
        filename = f"<{label}>"
        linecache.cache[filename] = (len(code), None, code.splitlines(keepends=True), filename)
        try:
            tree = ast.parse(code, filename=filename, mode="exec")
        except SyntaxError as error:
            result.error = "".join(traceback.format_exception_only(error))
            result.trace = trace_parts(error, None)
            return result
        trailing = tree.body.pop() if tree.body and isinstance(tree.body[-1], ast.Expr) else None
        stdout = io.StringIO()
        try:
            with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stdout):
                if tree.body:
                    exec(compile(tree, filename, "exec"), self.namespace)  # noqa: S102  # a REPL runs user code
                if trailing is not None:
                    value = eval(compile(ast.Expression(trailing.value), filename, "eval"), self.namespace)  # noqa: S307
                    if value is not None:
                        self.namespace["_"] = value
                        result.view = to_view(value)
                        if result.view is None:
                            result.result_repr = repr(value)
        except Exception as error:  # noqa: BLE001  # any user error is shown under the cell, not raised
            # drop this function's own frame so the traceback starts at the user's code
            tb = error.__traceback__.tb_next if error.__traceback__ else None
            result.error = "".join(traceback.format_exception(type(error), error, tb))
            result.trace = trace_parts(error, tb)
        result.stdout = stdout.getvalue()
        return result

    # -- data objects -----------------------------------------------------------

    def views(self) -> dict[str, View]:
        """A View for every public name bound to something render.py can show (DataFrames,
        pydantic models, ...), whether the agent or the user made it.
        """
        views: dict[str, View] = {}
        for name, value in self.namespace.items():
            if name.startswith("_") or name in BUILTIN_NAMES or isinstance(value, type):
                continue
            view = to_view(value)
            if view is not None:
                views[name] = view
        return views

    def tabs(self) -> dict[str, View]:
        """The views that have a tab: views() minus the closed ones
        still holding the value they were closed with.
        """
        views = self.views()
        self.closed = {
            name: value for name, value in self.closed.items() if name in views and self.namespace[name] is value
        }
        return {name: view for name, view in views.items() if name not in self.closed}

    def close_tabs(self, names: Iterable[str]) -> None:
        """Close tabs; their names stay bound in Python."""
        for name in names:
            if name in self.namespace:
                self.closed[name] = self.namespace[name]
                self.ui.pop(f"tab:{name}", None)

    def view_at(self, slot: str) -> View | None:
        """The View shown at a slot ('tab:<name>', 'chat:<name>'
        or 'cell:<id>'), if it still exists.

        A chat slot shows the same named value as its tab (with its own Ui).
        """
        kind, _, key = slot.partition(":")
        if kind in ("tab", "chat"):
            return to_view(self.namespace.get(key)) if key in self.views() else None
        return self.outputs.get(key)

    def put(self, slot: str, value: Any, inputs: dict[str, Any] | None = None) -> None:
        """Replace the value shown at a slot (eg another page of a video search).

        inputs: the tool inputs that made it (a tool form was run). Without them the value is
        taken as the same call's (another page), so the
        inputs recorded for the old value carry over.
        """
        kind, _, key = slot.partition(":")
        call_key = key if kind in ("tab", "chat") else slot
        old_view = self.view_at(slot)
        old = self.call_at(slot, old_view.value) if old_view else None
        if inputs is not None:
            self.calls[call_key] = Call(inputs, value, old.original if old else None, changed=True)
        elif old is not None:
            self.calls[call_key] = Call(old.inputs, value, old.original, old.changed)
        else:
            self.calls.pop(call_key, None)
        if kind in ("tab", "chat"):
            self.namespace[key] = value
        elif (view := to_view(value)) is not None:
            self.outputs[key] = view

    def call_at(self, slot: str, value: Any) -> Call | None:
        """The tool call that made the value shown at a slot; None when none is known (eg it
        was made in Python). A cell showing a named result (eg `r1`) finds that name's call.
        """
        kind, _, key = slot.partition(":")
        call = self.calls.get(key if kind in ("tab", "chat") else slot)
        if call is None or call.value is not value:
            call = next((call for call in self.calls.values() if call.value is value), None)
        return call

    def restore_original(self, slot: str) -> bool:
        """Put back the agent's own result and inputs at a slot whose tool form was re-run."""
        view = self.view_at(slot)
        call = self.call_at(slot, view.value) if view else None
        if call is None or call.original is None or not call.changed:
            return False
        inputs, value = call.original
        self.put(slot, value, inputs)
        kind, _, key = slot.partition(":")
        self.calls[key if kind in ("tab", "chat") else slot].changed = False
        return True

    def show(self, slot: str, compact: bool = False) -> ViewData:
        """What the browser gets for a slot: its view with
        the user's Ui (an empty one when gone).
        """
        # timed (the System tab): to_view on the value,
        # then filter / sort / rows for the browser
        with perf.span("build view"):
            view = self.view_at(slot)
            if view is None:
                return ViewData()
            call = self.call_at(slot, view.value)
            data = view.data(
                slot,
                self.ui.get(slot),
                compact,
                inputs=call.inputs if call else None,
                can_restore=bool(call and call.changed and call.original),
            )
        if view.kind == "smashdb":
            data.db_save_name = self.next_free_name("q")
        return data

    def next_free_name(self, prefix: str) -> str:
        """The first of prefix1, prefix2, ... not bound in
        Python (eg a SmashDb console's Save as).
        """
        return next(f"{prefix}{n}" for n in itertools.count(1) if f"{prefix}{n}" not in self.namespace)

    def name_problem(self, name: str, keep: str = "") -> str:
        """Why a name can't be bound by hand ("" if it can): a Python identifier, not private,
        not a keyword, not one of the names put in up front (pl, db), not `keep` (eg the
        console being saved from). An existing name is fine: it is replaced, as in Python.
        """
        if not name.isidentifier() or keyword.iskeyword(name):
            return f"{name!r} isn't a Python name"
        if name.startswith("_"):
            return "names starting with _ are hidden: pick another"
        if name in BUILTIN_NAMES:
            return f"{name} is predefined: pick another"
        if name == keep:
            return f"{name} is this console: pick another"
        return ""

    def bind_result(self, value: Any, source: str, inputs: dict[str, Any] | None = None, tool_call_id: str = "") -> str:
        """Bind a tool result to the next r<n> name. inputs: the arguments the tool was called
        with; tool_call_id: the agent's call that returned it ("" for a form added by hand).
        """
        self._table_count += 1
        name = f"r{self._table_count}"
        self.namespace[name] = value
        self.sources[name] = source
        if tool_call_id:
            self.tool_call_ids[name] = tool_call_id
        if inputs is not None:
            self.calls[name] = Call(inputs, value, original=(inputs, value))
        return name

    # -- clearing variables (the Variables pane) ----------------------------------

    def clear(self, names: Iterable[str]) -> list[str]:
        """Remove names from Python (as `del`), holding them as one batch that restore() can
        put back until purge() drops it. An earlier batch
        is purged first. Returns the names cleared.

        r<n> numbers are not given out again (_table_count stays), so "r2" in the chat never
        comes to mean another result.
        """
        wanted = [
            name for name in names if name in self.namespace and not name.startswith("_") and name not in BUILTIN_NAMES
        ]
        if not wanted:
            return []
        self.purge()
        self.freed = self.freed_names = 0
        for name in wanted:
            value = self.namespace.pop(name)
            self.trash[name] = Trashed(
                value,
                perf.rough_size(value),
                self.sources.pop(name, None),
                self.calls.pop(name, None),
                self.tool_call_ids.pop(name, None),
            )
            self.closed.pop(name, None)
            self.ui.pop(f"tab:{name}", None)
            self.ui.pop(f"chat:{name}", None)
        self.trash_seq += 1
        return wanted

    def restore(self) -> list[str]:
        """Undo the last clear. A name bound to something new since is left as it is now: those
        names are returned, and what they held before is dropped for good.
        """
        skipped = []
        for name, item in self.trash.items():
            if name in self.namespace:
                skipped.append(name)
                continue
            self.namespace[name] = item.value
            if item.source is not None:
                self.sources[name] = item.source
            if item.call is not None:
                self.calls[name] = item.call
            if item.tool_call_id is not None:
                self.tool_call_ids[name] = item.tool_call_id
        self.trash = {name: item for name, item in self.trash.items() if name in skipped}
        self.purge()
        self.freed = self.freed_names = 0  # an undo freed nothing worth a line
        self.trash_seq += 1
        return skipped

    def purge(self) -> list[str]:
        """Drop the cleared batch for good, with everything else here that holds one of its
        objects: `_`, a cell's result showing it, a tool call's record of it. Then collect, so
        the memory goes back now. Returns the ids of the cells whose result was dropped.

        An object still bound to another name (`a = r1`) is the user's to keep: nothing of it
        is dropped and it doesn't count as freed.
        """
        if not self.trash:
            return []
        bound = {id(value) for name, value in self.namespace.items() if name != "_"}
        gone = {id(item.value): item for item in self.trash.values() if id(item.value) not in bound}
        self.freed = sum(item.size for item in gone.values())
        self.freed_names = sum(id(item.value) in gone for item in self.trash.values())
        if id(self.namespace.get("_")) in gone:
            del self.namespace["_"]
        cells = [cell_id for cell_id, view in self.outputs.items() if id(view.value) in gone]
        for cell_id in cells:
            del self.outputs[cell_id]
            self.ui.pop(f"cell:{cell_id}", None)
            self.calls.pop(f"cell:{cell_id}", None)
        self.calls = {key: call for key, call in self.calls.items() if id(call.value) not in gone}
        for call in self.calls.values():
            if call.original is not None and id(call.original[1]) in gone:
                call.original = None
        self.trash = {}
        del gone  # the last references held here
        gc.collect()
        return cells

    # -- agent ------------------------------------------------------------------

    async def ask(
        self, prompt: str, on_delta: Callable[[str], Awaitable[None]], sent: str = "", toolsets: Any = None
    ) -> AiResult:
        """One agent turn. Text streams through on_delta; tool results
        with a view (tables, videos, models) become r1, r2, ...

        sent: the message as the model gets it, when that is more than what the user typed (the
        variables it mentions, mentions.with_context). toolsets: tools the app adds for this
        run (mentions.toolset), on top of the agent's own.
        """
        result = AiResult()
        # one "agent" record per turn (the debug panel, logs.py); each tool call logs its own
        # "tool" record, tagged with its tool_call_id (ds.ai.call_log.ToolCallLog)
        with log_call("agent", "smash-agent", name="turn", prompt=prompt) as call, capture_run_messages() as captured:
            if sent and sent != prompt:
                # what the model got on top of the typed prompt
                # (the debug log shows it, logs._agent)
                call["added"] = sent.removeprefix(prompt).strip()
            try:
                async with ds.ai.agent.run_stream(
                    sent or prompt, message_history=self.ai_history, toolsets=toolsets
                ) as stream:
                    async for delta in stream.stream_text(delta=True):
                        await on_delta(delta)
                    result.text = str(await stream.get_output())
                    new_messages = stream.new_messages()
                    self.ai_history = stream.all_messages()
            except Exception as error:  # noqa: BLE001  # model/tool failures are shown in the chat
                result.error = "".join(traceback.format_exception(error))
                result.trace = trace_parts(error, error.__traceback__)
                new_messages = captured[len(self.ai_history) :]
                call["error"] = f"{type(error).__name__}: {error}"
            result.steps = self._steps(new_messages)
            call["steps"] = len(result.steps)
            # from the messages rather than stream.usage(),
            # so a failed turn still shows what it spent
            result.usage = usage = TurnUsage.of(new_messages)
            self.ai_cost += usage.cost or 0
            if usage.requests:
                self.chat_tokens = usage.context_tokens
            usage.log_to(call)
        return result

    def _steps(self, messages: list[Any]) -> list[ToolStep]:
        steps: dict[str, ToolStep] = {}
        inputs: dict[str, dict[str, Any]] = {}
        for message in messages:
            for part in message.parts:
                if isinstance(part, ToolCallPart):
                    args = part.args_as_json_str()
                    if len(args) > MAX_ARGS_CHARS:
                        args = args[:MAX_ARGS_CHARS] + "…"
                    steps[part.tool_call_id] = ToolStep(tool=part.tool_name, args=args, call_id=part.tool_call_id)
                    with contextlib.suppress(Exception):  # arguments the model sent that aren't valid JSON
                        inputs[part.tool_call_id] = part.args_as_dict()
                elif isinstance(part, ToolReturnPart):
                    view = to_view(part.content)
                    if view is None:
                        continue
                    # a table is bound as its DataFrame; anything
                    # else as the object the tool returned
                    value = view.frame if isinstance(part.content, ds.ai.TableResult) else part.content
                    name = self.bind_result(value, part.tool_name, inputs.get(part.tool_call_id), part.tool_call_id)
                    if part.tool_call_id in steps:
                        steps[part.tool_call_id].result_name = name
                        steps[part.tool_call_id].result_label = view.summary
                        steps[part.tool_call_id].result_kind = view.kind
        return list(steps.values())


_SESSIONS: dict[str, Session] = {}


def find_session(token: str) -> Session | None:
    """The session for a browser tab if it has one; never
    creates it (completion, inline edit).
    """
    return _SESSIONS.get(token)


def get_session(token: str) -> Session:
    """The session for a browser tab, created on first use. Lives in server memory only."""
    if token not in _SESSIONS:
        _SESSIONS[token] = Session()
    session = _SESSIONS[token]
    session.used = time.time()
    return session


def all_sessions() -> dict[str, Session]:
    """Every session the backend holds, by token (the debug panel's System tab). They are never
    dropped: a browser tab that is gone keeps its variables until the backend restarts.
    """
    return dict(_SESSIONS)


def complete(token: str, code: str, line: int, column: int) -> list[dict[str, str]]:
    """Completions at (1-based line, 0-based column) of code,
    resolved against the session's live variables.

    Uses jedi's Interpreter mode, like IPython: `r1.` completes with real DataFrame methods
    because r1 exists. An unknown token completes against an
    empty namespace instead of creating a session.
    """
    session = find_session(token)
    namespace = session.namespace if session else {}
    try:
        found = jedi.Interpreter(code, [namespace]).complete(line, column)
    except Exception:  # noqa: BLE001  # completion is best-effort; never break typing
        return []
    public = [item for item in found if not item.name.startswith("_")] or found
    return [{"label": item.name, "type": item.type, "detail": item.type} for item in public[:MAX_COMPLETIONS]]
